func TestVGPUConfigAssertValid(t *testing.T) {
	testCases := []struct {
		description string
		config      VGPUConfig
		valid       bool
	}{
		{
			"Empty config",
			map[string]int{},
			true,
		},
		{
			"Valid config - one entry",
			map[string]int{
				"A100-5C": 1,
			},
			true,
		},
		{
			"Valid config - multiple entries",
			map[string]int{
				"A100-5C": 1,
				"A100-8C": 1,
			},
			true,
		},
		{
			"Invalid config - invalid count",
			map[string]int{
				"A100-5C": -1,
			},
			false,
		},
		{
			"Invalid config - all zero counts",
			map[string]int{
				"A100-5C": 0,
				"A100-8C": 0,
			},
			false,
		},
		{
			"Invalid config - malformed vGPU type",
			map[string]int{
				"A100-5c": 1,
			},
			false,
		},
		{
			"Invalid config - both time-sliced and MIG-back devices",
			map[string]int{
				"A100-5C":   1,
				"A100-1-5C": 1,
			},
			false,
		},
		{
			"Valid config - RTX Ada device",
			map[string]int{
				"RTX6000-Ada-2Q": 24,
			},
			true,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.description, func(t *testing.T) {
			err := tc.config.AssertValid()
			if tc.valid {
				require.Nil(t, err)
			} else {
				require.Error(t, err)
			}
		})
	}
}

